],
"explore":[],
"omitted":[
{"what":"Per-class precision, recall and F1","why":"No line to read them against, and they would not change what is unresolved."},
{"what":"Per-stratum pass rates","why":"The stratum split is not held for the pass rate."}
],
"next":[
{"text":"Declare a pass-rate line, and decide whether the urgent check belongs in the pass rule.","settles":"Whether {measure.passed.triage.mean} is good enough, or only label accuracy matters."},
{"text":"Inspect the urgent expectations on the failing cases, such as the phishing and double-charge cases.","settles":"Whether these are real misses or a check set too strict."}
],
"method":[
{"term":"Cases and repeats","text":"{measure.passed.triage.n_cases} cases, each run three times, giving {measure.passed.triage.n} trials. Intervals are over cases at 95%."},
{"term":"Pass","text":"The pass rule is pass^k with k=3 and no declared criterion. The reasons listed on failures are the label match and the urgent score."},
{"term":"Cost","text":"Production cost is {measure.production_replicating_cost.triage.mean} per request. The routing provider is not named."},
{"term":"Not compared","text":"No other arm, no control and no earlier run, so nothing is chosen.","caveats":["nothing_declared"]}
]
}
